import java.util.Scanner;

public class Main {
    public static long getGCD(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long X = sc.nextLong();
        long Y = sc.nextLong();
        long N = sc.nextLong();

        long bestA = 0;
        long bestB = 1;
        double minDiff = 1e12;

        for (long b = 1; b <= N; b++) {
            long left = 0, right = 100000;
            long a = 0;
            while (left <= right) {
                long mid = (left + right) >> 1;
                if (mid * Y <= X * b) {
                    a = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            left = 0;
            right = 100000;
            long a2 = 0, b2 = b;
            while (left <= right) {
                long mid = (left + right) >> 1;
                if (mid * Y < X * b) {
                    left = mid + 1;
                } else {
                    a2 = mid;
                    right = mid - 1;
                }
            }

            double diff2 = Math.abs((double) a2 / b2 - (double) X / Y);
            double diff1 = Math.abs((double) a / b - (double) X / Y);

            if (diff2 + 1e-8 < diff1) {
                a = a2;
                b = b2;
                diff1 = diff2;
            }

            long g = getGCD(a, b);
            if (diff1 < minDiff) {
                bestA = a / g;
                bestB = b / g;
                minDiff = diff1;
            }
        }

        System.out.println(bestA + "/" + bestB);
        sc.close();
    }
}
